@dataclass
class Case:
    """One held-out forecast task and its evaluator-only ground truth."""

    task: ForecastTask
    observed: pd.DataFrame
    reference: Reference
    manifest: dict[str, Any]


_DEFAULTS = {
    "white_noise": {"mean": 0.0, "sigma": 1.0},
    "trend": {"intercept": 0.0, "slope": 0.1, "sigma": 1.0},
    "seasonal": {"mean": 0.0, "amplitude": 1.0, "period": 12.0, "sigma": 1.0},
    "ar1": {"mean": 0.0, "phi": 0.8, "sigma": 1.0},
    "random_walk": {"intercept": 0.0, "drift": 0.0, "sigma": 1.0},
}

CORE_KINDS = tuple(_DEFAULTS)

